export { anatomy, type InputPart, parts } from "./input.anatomy";
export { connect } from "./input.connect";
export { getControlEl, getControlId, getRootId, getVisibilityTriggerId } from "./input.dom";
export { machine } from "./input.machine";
export type {
  InputApi,
  InputMachineProps,
  InputSchema,
  InputShape,
  InputValueChangeDetails,
  ResolvedInputMachineProps,
} from "./input.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type InputPart = "root" | "control" | "visibilityTrigger";

export const anatomy: Anatomy<InputPart> = createAnatomy("input").parts(
  "root",
  "control",
  "visibilityTrigger",
);

export const parts: Record<InputPart, AnatomyPart> = anatomy.build();

import { ariaAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./input.anatomy";
import { getControlId, getRootId, getVisibilityTriggerId } from "./input.dom";
import type { InputApi, InputSchema } from "./input.types";

export function connect<T extends PropTypes>(
  service: Service<InputSchema>,
  normalize: NormalizeProps<T>,
): InputApi<T> {
  const { context, prop, computed, state, send, scope } = service;

  const value = context.get("value");
  const disabled = prop("disabled");
  const invalid = prop("invalid");
  const readOnly = prop("readOnly");
  const masked = context.get("masked");
  const isPassword = computed("isPassword");
  const focused = state.matches("focused");
  // The source is read once, when focus lands, and held: the modality of `now`
  // flips to pointer after 300ms of mouse movement whether or not the focus
  // moved, and a ring that blinks out under the user's hands was the result.
  const focusSource = focused ? context.get("focusSource") : null;
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);
  // What the field *is*, which is the one thing the type can settle, and all it
  // buys now is the search field's own inline padding (CDC §4.2, amendment of
  // 2026-08-30). The shape left with the amendment of 2026-08-31: how a field is
  // drawn is a design choice no type can make, so it is a prop. The declared
  // type, not the resolved one — that one turns a revealed password into text.
  const isSearch = prop("type") === "search";

  const stateAttrs = {
    "data-disabled": dataAttr(disabled),
    "data-invalid": dataAttr(invalid),
    "data-readonly": dataAttr(readOnly),
    "data-focus-visible": dataAttr(focusVisible),
    "data-focus-source": focusSource ?? undefined,
    // Not `data-snav-focused`: that attribute belongs to `@standarx/nav`'s spatial
    // engine, and the styles hang the tvOS lift off it. Emitting it here would
    // lift the root and the control at once, and break the engine's "exactly one
    // focused node" invariant.
    "data-focus": dataAttr(focused),
  };

  // Shared by the single-line and multi-line controls: same behaviour, different
  // element. Only `type` belongs to one of them.
  const controlProps = {
    ...parts.control.attrs,
    ...stateAttrs,
    id: getControlId(scope),
    dir: prop("dir"),
    value,
    disabled,
    readOnly,
    required: prop("required"),
    name: prop("name"),
    form: prop("form"),
    placeholder: prop("placeholder"),
    maxLength: prop("maxLength"),
    // WCAG 2.2 SC 1.3.5 lives on this one, and a mobile keyboard on the other.
    autoComplete: prop("autoComplete"),
    inputMode: prop("inputMode"),
    "aria-invalid": ariaAttr(invalid),
    "aria-describedby": prop("describedBy"),
    onInput(event: Event) {
      if (event.defaultPrevented) return;
      const target = event.target as HTMLInputElement | HTMLTextAreaElement | null;
      if (target !== null) send({ type: "VALUE.SET", value: target.value });
    },
    onKeyDown(event: KeyboardEvent) {
      if (event.defaultPrevented || event.key !== "Escape" || !prop("clearOnEscape")) return;
      // Only when there is something to clear: otherwise Escape belongs to
      // whatever is above — a popover, a dialog — and swallowing it here would
      // leave the user unable to close it from inside the field.
      if (value === "") return;
      event.preventDefault();
      send({ type: "VALUE.CLEAR" });
    },
    onFocus(event: FocusEvent) {
      if (event.defaultPrevented) return;
      send({ type: "CONTROL.FOCUS" });
    },
    onBlur(event: FocusEvent) {
      if (event.defaultPrevented) return;
      send({ type: "CONTROL.BLUR" });
    },
  };

  return {
    value,
    disabled,
    invalid,
    focusSource,
    focusVisible,
    masked,

    setValue(next: string): void {
      send({ type: "VALUE.SET", value: next });
    },
    clear(): void {
      send({ type: "VALUE.CLEAR" });
    },
    toggleVisibility(): void {
      send({ type: "VISIBILITY.TOGGLE" });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        ...stateAttrs,
        id: getRootId(scope),
        dir: prop("dir"),
        "data-variant": isSearch ? "search" : undefined,
        "data-shape": prop("shape"),
      }),

    getControlProps: (): T["input"] =>
      normalize.input({ ...controlProps, type: computed("resolvedType") }),

    getTextareaProps: (): T["textarea"] => normalize.textarea(controlProps),

    getVisibilityTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.visibilityTrigger.attrs,
        // Deliberately not `stateAttrs`: this button is its own focusable, and
        // wearing the control's focus state would ring it whenever the field is
        // focused.
        "data-disabled": dataAttr(disabled),
        "data-invalid": dataAttr(invalid),
        id: getVisibilityTriggerId(scope),
        type: "button",
        disabled,
        hidden: !isPassword,
        "aria-controls": getControlId(scope),
        "aria-pressed": masked ? "false" : "true",
        "data-state": masked ? "masked" : "visible",
        // "Does not move the focus" is about the pointer: a mouse click on the
        // eye must not take the caret out of the field. It stays focusable, and
        // Tab reaches it — a reveal a keyboard user cannot operate is not a
        // reveal.
        onMouseDown(event) {
          if (event.defaultPrevented) return;
          event.preventDefault();
        },
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "VISIBILITY.TOGGLE" });
        },
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "input";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getControlId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "control");
}

export function getVisibilityTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "visibilityTrigger");
}

export function getControlEl(scope: Scope): HTMLElement | null {
  return scope.getById(getControlId(scope));
}

/**
 * One machine for the text field, the multi-line field and the password field:
 * they differ in which element renders and whether the characters are hidden,
 * not in what they do. That is CDC D10 in the small — one machine, several
 * presentations — and it is why `password-input` is not a component of its own.
 *
 * The value is a bindable like any other, so a text field is controlled or
 * uncontrolled by the same rule as a checkbox. The DOM's own value is the source
 * of truth while typing; the machine only records what the browser reports.
 */

import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import type { InputSchema } from "./input.types";

export const machine: Machine<InputSchema> = createMachine<InputSchema>({
  props({ props }) {
    return {
      type: "text",
      shape: "capsule",
      disabled: false,
      invalid: false,
      readOnly: false,
      required: false,
      clearOnEscape: false,
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<string>(() => ({
        defaultValue: prop("defaultValue") ?? "",
        value: prop("value"),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "input value",
      })),
      masked: bindable<boolean>(() => ({ defaultValue: prop("defaultMasked") ?? true })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  computed: {
    isPassword: ({ prop }) => prop("type") === "password",
    // A revealed password is a text field to the browser — which is also what
    // stops a password manager from re-masking it.
    resolvedType({ prop, context }) {
      if (prop("type") !== "password") return prop("type");
      return context.get("masked") ? "password" : "text";
    },
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality"],

  on: {
    "VALUE.SET": { guard: "isInteractive", actions: ["setValue"] },
    "VALUE.CLEAR": { guard: "isInteractive", actions: ["clearValue"] },
    "VISIBILITY.TOGGLE": { actions: ["toggleMasked"] },
    "CONTROL.FOCUS": { target: "focused", actions: ["captureFocusSource"] },
  },

  states: {
    idle: {},
    focused: {
      exit: ["clearFocusSource"],
      on: { "CONTROL.BLUR": { target: "idle" } },
    },
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled") && !prop("readOnly"),
    },

    actions: {
      setValue({ context, event }) {
        if (event.type === "VALUE.SET") context.set("value", event.value);
      },
      clearValue({ context }) {
        context.set("value", "");
      },
      toggleMasked({ context }) {
        context.set("masked", (masked) => !masked);
      },
      captureFocusSource({ context, scope }) {
        context.set("focusSource", getInputModality(scope.getDoc()));
      },
      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },
    },

    effects: {
      // No listener: the source is read once, when focus lands, so a modality
      // change no longer has to reach every mounted control. Holding the handle
      // is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality } from "../../types";

export interface InputValueChangeDetails {
  readonly value: string;
}

/**
 * How the field is drawn (CDC §4.2, amendment of 2026-08-31). `capsule` is the
 * default and the shape search has always had; `rect` is the rounded
 * rect; `soft` is the value between the two. The type
 * still says what a field *is* — it cannot say how it is drawn.
 */
export type InputShape = "capsule" | "soft" | "rect";

export interface InputMachineProps {
  readonly dir?: Direction | undefined;
  readonly value?: string | undefined;
  readonly defaultValue?: string | undefined;
  readonly type?: string | undefined;
  readonly shape?: InputShape | undefined;
  readonly placeholder?: string | undefined;
  readonly disabled?: boolean | undefined;
  readonly invalid?: boolean | undefined;
  readonly readOnly?: boolean | undefined;
  readonly required?: boolean | undefined;
  readonly name?: string | undefined;
  readonly form?: string | undefined;
  readonly autoComplete?: string | undefined;
  readonly inputMode?: string | undefined;
  readonly maxLength?: number | undefined;
  /** Ids of the text describing this control — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  /** Escape empties the control. Off by default; a search field turns it on. */
  readonly clearOnEscape?: boolean | undefined;
  /** Starts masked when the type is `password`; the trigger flips it. */
  readonly defaultMasked?: boolean | undefined;
  readonly onValueChange?: ((details: InputValueChangeDetails) => void) | undefined;
}

export interface ResolvedInputMachineProps extends InputMachineProps {
  readonly type: string;
  readonly shape: InputShape;
  readonly disabled: boolean;
  readonly invalid: boolean;
  readonly readOnly: boolean;
  readonly required: boolean;
  readonly clearOnEscape: boolean;
}

export interface InputSchema extends MachineSchema {
  state: "idle" | "focused";
  props: ResolvedInputMachineProps;
  context: { value: string; masked: boolean; focusSource: InputModality | null };
  computed: { isPassword: boolean; resolvedType: string };
  event:
    | { type: "VALUE.SET"; value: string }
    | { type: "VALUE.CLEAR" }
    | { type: "VISIBILITY.TOGGLE" }
    | { type: "CONTROL.FOCUS" }
    | { type: "CONTROL.BLUR" };
  action: "setValue" | "clearValue" | "toggleMasked" | "captureFocusSource" | "clearFocusSource";
  guard: "isInteractive";
  effect: "trackModality";
}

export interface InputApi<T extends PropTypes = PropTypes> {
  readonly value: string;
  readonly disabled: boolean;
  readonly invalid: boolean;
  /** The modality focus arrived under, or `null` while this is not focused. */
  readonly focusSource: InputModality | null;
  /** True only while focused, and only when that source warrants a ring. */
  readonly focusVisible: boolean;
  /** Only meaningful for a password: whether the characters are hidden. */
  readonly masked: boolean;
  setValue(value: string): void;
  clear(): void;
  toggleVisibility(): void;
  getRootProps(): T["element"];
  getControlProps(): T["input"];
  getTextareaProps(): T["textarea"];
  getVisibilityTriggerProps(): T["button"];
}

/**
 * `<Input/>` — one root, one control (or, under `multiline`, one textarea), and
 * the reveal trigger the machine positions but never names.
 *
 * `revealLabel` is the exigence this layer exists to enforce: `type="password"`
 * has to make it required, because `getVisibilityTriggerProps`
 * (`input.connect.ts:124-151`) writes an id, a state and a click handler and no
 * `aria-label` at all — the machine only ever *hides* the button when the field
 * is not a password (`hidden: !isPassword`), it never names it. Skip the label
 * and the trigger ships as a button a screen reader announces as "button".
 *
 * The union below only reaches literal usage: `<Input type="password"/>` with no
 * `revealLabel` is a compile error, because `"password"` is the one literal
 * value either branch's `type` field can match on its own. `type={someString}`
 * is still plain `string` to the compiler, though, the same way a computed
 * `Dialog.title` slips past `Exclude<ReactNode, …>` — so a `type` read out of
 * state or a prop lands in the loose branch and typechecks with no
 * `revealLabel` at all. The dev-only `warn` below is what the type system
 * cannot be for that case, and it is also what catches a plain-JS caller with no
 * type checker in the loop.
 *
 * `InputComposedProps` has to stay an actual union for that compile-time check
 * to mean anything, and an `interface` cannot hold one — so the fields every
 * input shares live on `InputBaseComposedProps`, and only `type`/`revealLabel`
 * are decided by the pair below.
 */

import { isDev, warn } from "@standarui/core";
import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  InputControl,
  InputRoot,
  InputTextarea,
  InputVisibilityTrigger,
  type UseInputProps,
} from "./input";

export interface InputParts {
  readonly control?: PartProps<"input"> | undefined;
  readonly textarea?: PartProps<"textarea"> | undefined;
  readonly visibilityTrigger?: PartProps<"button"> | undefined;
}

export interface InputBaseComposedProps
  extends Omit<UseInputProps, "type">,
    Omit<PartProps<"div", UseInputProps>, "children"> {
  /** Renders `InputTextarea` in place of `InputControl`. */
  readonly multiline?: boolean | undefined;
  readonly parts?: InputParts | undefined;
}

/**
 * The pair no single `interface` can hold: `revealLabel` is absent everywhere
 * `type` is not the literal `"password"`, and required the one place it is.
 */
type InputRevealProps =
  | { readonly type?: string | undefined; readonly revealLabel?: undefined }
  | { readonly type: "password"; readonly revealLabel: string };

export type InputComposedProps = InputBaseComposedProps & InputRevealProps;

export function Input(props: InputComposedProps): ReactNode {
  const { multiline, revealLabel, parts, ...root } = props;
  const isPassword = root.type === "password";

  // The half the union cannot state: a `type` read from a variable is plain
  // `string`, so it lands in the loose branch and compiles with no
  // `revealLabel` at all — this is that case, caught at render instead.
  warn(
    isDev() && isPassword && (revealLabel === undefined || revealLabel === ""),
    'Input: `revealLabel` names the reveal trigger and is required under type="password" — `getVisibilityTriggerProps` writes no accessible name of its own. Pass the word, or the trigger ships as a button called "button".',
  );

  return (
    <InputRoot {...root}>
      {multiline === true ? (
        <InputTextarea {...parts?.textarea} />
      ) : (
        <InputControl {...parts?.control} />
      )}
      {isPassword ? (
        <InputVisibilityTrigger aria-label={revealLabel} {...parts?.visibilityTrigger} />
      ) : null}
    </InputRoot>
  );
}

export type { InputMachineProps, InputValueChangeDetails } from "@standarui/core/input";
export {
  Input,
  type InputBaseComposedProps,
  type InputComposedProps,
  type InputParts,
} from "./composed";
export {
  type InputApi,
  InputControl,
  InputRoot,
  type InputRootProps,
  InputTextarea,
  InputVisibilityTrigger,
  type UseInputProps,
  useInput,
} from "./input";

import * as input from "@standarui/core/input";
import type { ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { inheritFromField, useFieldContext } from "../../field-context";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type InputApi = input.InputApi<ReactPropTypes>;

const InputContext = createPartContext<InputApi>("Input");

export interface UseInputProps extends input.InputMachineProps, MachineRuntimeProps {}

export function useInput(props: UseInputProps): InputApi {
  return input.connect(useMachine(input.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "value",
  "defaultValue",
  "type",
  "shape",
  "placeholder",
  "disabled",
  "invalid",
  "readOnly",
  "required",
  "name",
  "form",
  "autoComplete",
  "inputMode",
  "maxLength",
  "describedBy",
  "clearOnEscape",
  "defaultMasked",
  "onValueChange",
] as const;

export interface InputRootProps extends UseInputProps, PartProps<"div", UseInputProps> {}

export function InputRoot(props: InputRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();

  const api = useInput({
    ...inheritFromField(machineProps, field),
    ids: { control: field?.controlProps.id, ...machineProps.ids },
  });

  return (
    <InputContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </InputContext.Provider>
  );
}

export const InputControl: (props: PartProps<"input">) => ReactNode = createPart(InputContext, {
  name: "InputControl",
  element: "input",
  props: (api) => api.getControlProps(),
});

export const InputTextarea: (props: PartProps<"textarea">) => ReactNode = createPart(InputContext, {
  name: "InputTextarea",
  element: "textarea",
  props: (api) => api.getTextareaProps(),
});

export const InputVisibilityTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  InputContext,
  {
    name: "InputVisibilityTrigger",
    element: "button",
    props: (api) => api.getVisibilityTriggerProps(),
  },
);
